const body = $input.first().json.body || $input.first().json;

const projectId = body.project_id || null;
const action    = body.action    || 'advance';

if (!projectId) {
  throw new Error('project_id es obligatorio');
}

return [{ json: { project_id: projectId, action: action } }];

const project = $input.first().json;
const action  = $('Extract Input').first().json.action;

if (!project || !project.id) {
  throw new Error('Proyecto no encontrado: ' + $('Extract Input').first().json.project_id);
}

return [{
  json: {
    ...project,
    project_id:          project.id,
    action:              action,
    pending_approvals:   parseInt(project.pending_approvals) || 0
  }
}];

const briefingResult = $input.first().json;
const project = $('Prepare Project Data').first().json;

// Evaluar resultado del agente de briefing
const status = briefingResult.status || 'unknown';

return [{
  json: {
    project_id:      project.id,
    project_name:    project.name,
    phase_executed:  'intake',
    agent_result:    status,
    briefing_status: status,
    advance_phase:   status === 'complete'
  }
}];

const r = $input.first().json;
const p = $('Prepare Project Data').first().json;
const s = r.status || 'unknown';
const complete = s === 'complete';
return [{ json: {
  project_id: p.id,
  current_phase: p.current_phase,
  agent_result: s,
  advance_phase: complete,
  plan_id: r.plan_id || null,
  total_weeks: r.total_weeks || null,
  phases_count: r.phases_count || null,
  total_duration_days: r.total_duration_days || null
} }];

const r = $input.first().json;
const p = $('Prepare Project Data').first().json;
return [{ json: {
  project_id: p.id,
  agent_result: r.status || 'unknown',
  memory_case_id: r.memory_case_id || null,
  lessons_count: r.lessons_count || 0,
  success: r.status === 'complete'
} }];

const wh = $('Orchestrator Entry').first().json || {};
const headers = wh.headers || {};
const sourceIp = headers['x-real-ip']
  || (headers['x-forwarded-for'] || '').toString().split(',')[0].trim()
  || 'unknown';
const body = wh.body || {};
const out = {
  source_ip: sourceIp,
  user_agent: headers['user-agent'] || 'unknown',
  endpoint: '/webhook/orchestrator',
  max_per_minute: 60,
  agent_name: 'main_orchestrator',
  project_id: body.project_id || null
};
return [{ json: out }];

const item = $input.first().json;
const projectId = $('Prepare Project Data').first().json.id;
const projectName = $('Prepare Project Data').first().json.name || 'unknown';
const currentPhase = item.current_phase || $('Prepare Project Data').first().json.current_phase || 'unknown';

// Mapeo phase->agent (cual agente se ejecuta en cada case del Switch del orchestrator)
const phaseToAgent = {
  'intake': 'agent_briefing',
  'briefing_done': 'agent_design',
  'design_done': 'agent_documents+agent_regulatory',
  'analysis_done': 'agent_materials',
  'costs_done': 'agent_documents+agent_trades',
  'trades_done': 'agent_proposal',
  'approved': 'agent_planner',
  'planning_done': 'agent_memory'
};
const agentName = phaseToAgent[currentPhase] || 'unknown_agent';

// El error de executeWorkflow puede venir como string (item.error) o como objeto (item.error.message)
let errorMessage = 'Unknown error';
let errorStack = '';
if (typeof item.error === 'string') {
  errorMessage = item.error.substring(0, 500);
} else if (item.error && typeof item.error === 'object') {
  errorMessage = (item.error.message || item.error.description || JSON.stringify(item.error)).toString().substring(0, 500);
  errorStack = (item.error.stack || '').toString().substring(0, 4000);
}

const executionId = $execution?.id || null;

return [{
  json: {
    project_id: projectId,
    project_name: projectName,
    phase_at_error: currentPhase,
    agent_name: agentName,
    error_message: errorMessage,
    error_stack: errorStack,
    execution_id: executionId,
    timestamp: new Date().toISOString()
  }
}];

const err = $input.first().json;
return [{
  json: {
    statusCode: 500,
    status: 'error',
    project_id: err.project_id,
    agent: err.agent_name,
    phase_at_error: err.phase_at_error,
    error_message: err.error_message,
    timestamp: err.timestamp
  }
}];

